INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0006-0001-0001-000000000001', '22222222-0001-0001-0001-000000000006', 'Below Zero', 'Discover how Chinese and Indian mathematicians embraced numbers less than nothing', 1, 'tutorial', 15, 5, 200, 'Liu Hui',
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0601-0001-0001-000000000001', '33333333-0006-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which civilization first used negative numbers around 200 BCE?', NULL, '[{"id":"a","text":"Greek"},{"id":"b","text":"Egyptian"},{"id":"c","text":"Chinese"},{"id":"d","text":"Roman"}]'::jsonb, '"c"'::jsonb, 'The Chinese used colored counting rods — red for positive, black for negative — for bookkeeping as early as 200 BCE.', 'Think about colored counting rods', 5, 1),
('44444444-0601-0001-0001-000000000002', '33333333-0006-0001-0001-000000000001', 'multiple_choice', 'easy', 'Which number is smaller: -3 or -7?', NULL, '[{"id":"a","text":"-3"},{"id":"b","text":"-7"},{"id":"c","text":"They are equal"},{"id":"d","text":"Cannot compare"}]'::jsonb, '"b"'::jsonb, '-7 is smaller (further left on the number line). Think of temperature: -7°C is colder than -3°C.', 'Think of a thermometer — which is colder?', 5, 2),
('44444444-0601-0001-0001-000000000003', '33333333-0006-0001-0001-000000000001', 'true_false', 'easy', 'True or False: 0 is a negative number.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"false"'::jsonb, 'False! Zero is neither positive nor negative. It sits exactly between them on the number line.', 'Zero is the boundary between positive and negative', 5, 3),
('44444444-0601-0001-0001-000000000004', '33333333-0006-0001-0001-000000000001', 'fill_in_blank', 'easy', 'The temperature is -5°C and drops 3 more degrees. What is the new temperature? (Include the minus sign)', NULL, NULL, '"-8"'::jsonb, '-5 - 3 = -8°C. Moving further below zero.', 'Going down from -5 means getting more negative', 5, 4),
('44444444-0601-0001-0001-000000000005', '33333333-0006-0001-0001-000000000001', 'multiple_choice', 'easy', 'What is the opposite of -4?', NULL, '[{"id":"a","text":"-4"},{"id":"b","text":"4"},{"id":"c","text":"0"},{"id":"d","text":"-1/4"}]'::jsonb, '"b"'::jsonb, 'The opposite of -4 is +4. They are the same distance from zero but on opposite sides.', 'Same distance from zero, other direction', 5, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0006-0001-0001-000000000002', '22222222-0001-0001-0001-000000000006', 'Adding & Subtracting Negatives', 'Master the rules for adding and subtracting negative numbers', 2, 'practice', 15, 7, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0602-0001-0001-000000000001', '33333333-0006-0001-0001-000000000002', 'fill_in_blank', 'easy', 'What is 5 + (-3)?', '5 + (-3) = ?', NULL, '"2"'::jsonb, '5 + (-3) = 5 - 3 = 2. Adding a negative is the same as subtracting.', 'Adding a negative is like subtracting', 5, 1),
('44444444-0602-0001-0001-000000000002', '33333333-0006-0001-0001-000000000002', 'fill_in_blank', 'easy', 'What is -4 + (-6)?', '(-4) + (-6) = ?', NULL, '"-10"'::jsonb, '-4 + (-6) = -10. Adding two negatives gives a more negative result.', 'Two debts add up to a bigger debt', 5, 2),
('44444444-0602-0001-0001-000000000003', '33333333-0006-0001-0001-000000000002', 'fill_in_blank', 'medium', 'What is -8 + 12?', '(-8) + 12 = ?', NULL, '"4"'::jsonb, '-8 + 12 = 4. Start at -8 on the number line and move 12 steps right.', 'Start at -8, move right by 12', 10, 3),
('44444444-0602-0001-0001-000000000004', '33333333-0006-0001-0001-000000000002', 'multiple_choice', 'medium', 'What is 3 - (-5)?', '3 - (-5) = ?', '[{"id":"a","text":"-2"},{"id":"b","text":"2"},{"id":"c","text":"8"},{"id":"d","text":"-8"}]'::jsonb, '"c"'::jsonb, '3 - (-5) = 3 + 5 = 8. Subtracting a negative is the same as adding!', 'Two negatives make a positive: minus a minus = plus', 10, 4),
('44444444-0602-0001-0001-000000000005', '33333333-0006-0001-0001-000000000002', 'fill_in_blank', 'medium', 'What is -15 + 15?', '(-15) + 15 = ?', NULL, '"0"'::jsonb, 'A number plus its opposite always equals zero. -15 + 15 = 0.', 'A number and its opposite cancel out', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0006-0001-0001-000000000003', '22222222-0001-0001-0001-000000000006', 'Multiplying & Dividing Negatives', 'Learn the sign rules for multiplication and division', 3, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0603-0001-0001-000000000001', '33333333-0006-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is -3 × 4?', '(-3) \\times 4 = ?', NULL, '"-12"'::jsonb, 'Negative × positive = negative. 3 × 4 = 12, so -3 × 4 = -12.', 'Different signs → negative result', 5, 1),
('44444444-0603-0001-0001-000000000002', '33333333-0006-0001-0001-000000000003', 'fill_in_blank', 'easy', 'What is -5 × (-2)?', '(-5) \\times (-2) = ?', NULL, '"10"'::jsonb, 'Negative × negative = positive! 5 × 2 = 10, so -5 × -2 = 10.', 'Same signs → positive result', 5, 2),
('44444444-0603-0001-0001-000000000003', '33333333-0006-0001-0001-000000000003', 'true_false', 'easy', 'True or False: A negative number multiplied by a negative number gives a positive result.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Negative × negative = positive. Think of it as: reversing a reversal brings you back to the original direction.', 'What happens when you reverse a reverse?', 5, 3),
('44444444-0603-0001-0001-000000000004', '33333333-0006-0001-0001-000000000003', 'fill_in_blank', 'medium', 'What is -20 ÷ (-4)?', '(-20) \\div (-4) = ?', NULL, '"5"'::jsonb, 'Same signs → positive result. 20 ÷ 4 = 5.', 'Same signs give a positive answer', 10, 4),
('44444444-0603-0001-0001-000000000005', '33333333-0006-0001-0001-000000000003', 'multiple_choice', 'medium', 'What is (-2) × (-3) × (-1)?', NULL, '[{"id":"a","text":"6"},{"id":"b","text":"-6"},{"id":"c","text":"5"},{"id":"d","text":"-5"}]'::jsonb, '"b"'::jsonb, '(-2) × (-3) = 6, then 6 × (-1) = -6. An odd number of negatives gives a negative result.', 'Count the negative signs: odd = negative, even = positive', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0006-0001-0001-000000000004', '22222222-0001-0001-0001-000000000006', 'Number Line Mastery', 'Navigate the number line like a pro with positive and negative numbers', 4, 'practice', 15, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0604-0001-0001-000000000001', '33333333-0006-0001-0001-000000000004', 'multiple_choice', 'easy', 'On a number line, which direction do you move to add a positive number?', NULL, '[{"id":"a","text":"Left"},{"id":"b","text":"Right"},{"id":"c","text":"Up"},{"id":"d","text":"It depends"}]'::jsonb, '"b"'::jsonb, 'Adding a positive number means moving RIGHT on the number line. Adding a negative means moving LEFT.', 'Positive = right, negative = left', 5, 1),
('44444444-0604-0001-0001-000000000002', '33333333-0006-0001-0001-000000000004', 'fill_in_blank', 'easy', 'What number is exactly halfway between -4 and 2 on the number line?', NULL, NULL, '"-1"'::jsonb, 'The midpoint of -4 and 2 is (-4 + 2) ÷ 2 = -2 ÷ 2 = -1.', 'Add the two numbers and divide by 2', 5, 2),
('44444444-0604-0001-0001-000000000003', '33333333-0006-0001-0001-000000000004', 'fill_in_blank', 'medium', 'What is the distance between -7 and 3 on the number line?', NULL, NULL, '"10"'::jsonb, 'Distance = |(-7) - 3| = |-10| = 10. Or count: from -7 to 0 is 7 steps, from 0 to 3 is 3 steps, total 10.', 'Count from -7 to 0, then from 0 to 3', 10, 3),
('44444444-0604-0001-0001-000000000004', '33333333-0006-0001-0001-000000000004', 'multiple_choice', 'medium', 'Which list is in order from least to greatest?', NULL, '[{"id":"a","text":"-1, -5, 0, 3, 7"},{"id":"b","text":"-5, -1, 0, 3, 7"},{"id":"c","text":"0, -1, -5, 3, 7"},{"id":"d","text":"7, 3, 0, -1, -5"}]'::jsonb, '"b"'::jsonb, '-5 is the smallest (furthest left), then -1, then 0, then 3, then 7.', 'The more negative, the smaller the number', 10, 4),
('44444444-0604-0001-0001-000000000005', '33333333-0006-0001-0001-000000000004', 'fill_in_blank', 'medium', 'What is the absolute value of -13? (Just the number)', NULL, NULL, '"13"'::jsonb, '|-13| = 13. Absolute value is the distance from zero, always positive.', 'How far is -13 from zero?', 10, 5)
INSERT INTO lessons (id, unit_id, name, description, order_index, lesson_type, xp_reward, estimated_minutes, origin_year, origin_figure, history_intro) VALUES
('33333333-0006-0001-0001-000000000005', '22222222-0001-0001-0001-000000000006', 'Negative Numbers Boss', 'Show your mastery of negative numbers!', 5, 'boss_round', 30, 5, NULL, NULL, NULL)
INSERT INTO questions (id, lesson_id, question_type, difficulty, question_text, question_latex, options, correct_answer, explanation, hint, xp_value, order_index) VALUES
('44444444-0605-0001-0001-000000000001', '33333333-0006-0001-0001-000000000005', 'fill_in_blank', 'medium', 'What is -8 - (-3) + (-2)?', '(-8) - (-3) + (-2) = ?', NULL, '"-7"'::jsonb, '-8 - (-3) + (-2) = -8 + 3 + (-2) = -8 + 3 - 2 = -7.', 'Convert subtracting a negative to adding, then work left to right', 10, 1),
('44444444-0605-0001-0001-000000000002', '33333333-0006-0001-0001-000000000005', 'fill_in_blank', 'medium', 'What is (-6)²?', '(-6)^2 = ?', NULL, '"36"'::jsonb, '(-6)² = (-6) × (-6) = 36. Squaring a negative gives a positive.', 'Negative times negative = positive', 10, 2),
('44444444-0605-0001-0001-000000000003', '33333333-0006-0001-0001-000000000005', 'multiple_choice', 'hard', 'The temperature was -3°C at midnight. By noon it had risen 15 degrees, then dropped 8 degrees by evening. What was the evening temperature?', NULL, '[{"id":"a","text":"4°C"},{"id":"b","text":"6°C"},{"id":"c","text":"10°C"},{"id":"d","text":"-4°C"}]'::jsonb, '"a"'::jsonb, '-3 + 15 = 12, then 12 - 8 = 4°C.', 'Start at -3, go up 15, then down 8', 15, 3),
('44444444-0605-0001-0001-000000000004', '33333333-0006-0001-0001-000000000005', 'fill_in_blank', 'hard', 'If x = -4, what is 2x² - 3x?', '2x^2 - 3x \\text{ when } x = -4', NULL, '"44"'::jsonb, '2(-4)² - 3(-4) = 2(16) - (-12) = 32 + 12 = 44.', 'Remember: (-4)² = 16, and -3 × -4 = 12', 15, 4),
('44444444-0605-0001-0001-000000000005', '33333333-0006-0001-0001-000000000005', 'true_false', 'hard', 'True or False: -(-(-5)) = -5', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]'::jsonb, '"true"'::jsonb, 'True! Work from inside out: -5 → -(-5) = 5 → -(5) = -5. Three negations = negative (odd number of negatives).', 'Count the negative signs: odd or even?', 15, 5)
